const HALLVALLA_UNIT_SKILL_RARITY=Object.freeze({"Básica":1,"Rara":2,"Épica":3,"Gloriosa":4,"Mítica":5,"Legendaria":6,"Semidiós":7});
const HALLVALLA_UNIT_SKILL_MAX_TIER=15;

function hvSkillNorm(value){
  return String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim();
}
function hvSkillUnique(list){return [...new Set((Array.isArray(list)?list:[]).filter(Boolean))];}
function hvSkillRarityIndex(entity){
  const rarity=String(entity?.rarity||HALLVALLA_UNIT_SKILL_ASSIGNMENTS[String(entity?.key||"")]?.rarity||"Básica");
  return HALLVALLA_UNIT_SKILL_RARITY[rarity]||1;
}
function hvSkillTierFromRank(rank){return Math.max(1,Math.min(HALLVALLA_UNIT_SKILL_MAX_TIER,Math.ceil(Math.max(1,Number(rank)||1)/3)));}
function hvSkillOptionalNumber(value){
  if(value===null||value===undefined||value==="")return null;
  const n=Number(value);
  return Number.isFinite(n)?n:null;
}
const HALLVALLA_TRIGGER_SKILL_COOLDOWN_SECONDS=30;
function hvSkillUsesTriggerCooldown(skill){
  const trigger=hvSkillNorm(skill?.trigger);
  if(!trigger||trigger==="pasiva")return false;
  if(skill?.name==="Muro de Picas")return true;
  const passiveExact=new Set([
    "aliados cercanos",
    "unidad aliada mas adelantada",
    "por cada reanimado controlado",
    "a 2 casillas o menos del lider",
    "2+ caballerias aliadas proximas",
    "2+ aliados moviendose hacia mismo sector",
    "2+ aliados avanzan juntos",
    "2+ aliados atacan mismo objetivo",
    "3+ escuderos compatibles proximos",
    "bajo fuego de rango",
    "ruta lateral disponible",
    "durante desplazamiento"
  ]);
  if(passiveExact.has(trigger))return false;
  const passivePrefixes=[
    "mientras ",
    "junto a ",
    "adyacente a ",
    "en formacion",
    "detras de "
  ];
  return !passivePrefixes.some(prefix=>trigger.startsWith(prefix));
}function hvSkillActivationLabel(skill){
  const raw=String(skill?.trigger||"").trim();
  if(!raw)return "";
  if(hvSkillUsesTriggerCooldown(skill)&&/^cada\s+\d+(?:[.,]\d+)?\s*s\b/i.test(raw))return raw.replace(/^cada\s+\d+(?:[.,]\d+)?\s*s\b/i,"Cada 30 s");
  return raw;
}
function hvSkillScale(skill,entity){
  const rarity=skill?.simple?Math.min(6,hvSkillRarityIndex(entity)):hvSkillRarityIndex(entity);
  const base=hvSkillOptionalNumber(skill?.base),step=hvSkillOptionalNumber(skill?.step);
  const duration=hvSkillOptionalNumber(skill?.duration),durationStep=hvSkillOptionalNumber(skill?.durationStep);
  const proc=hvSkillOptionalNumber(skill?.proc),procStep=hvSkillOptionalNumber(skill?.procStep);
  const cooldown=hvSkillOptionalNumber(skill?.cooldown),cooldownStep=hvSkillOptionalNumber(skill?.cooldownStep);
  const triggerCooldown=hvSkillUsesTriggerCooldown(skill);
  return {
    rarity,
    value:Number.isFinite(base)?base+(rarity-1)*(Number.isFinite(step)?step:0):null,
    duration:Number.isFinite(duration)?Math.max(0,duration+(rarity-1)*(Number.isFinite(durationStep)?durationStep:0)):null,
    proc:Number.isFinite(proc)?Math.max(0,Math.min(100,proc+(rarity-1)*(Number.isFinite(procStep)?procStep:0))):null,
    cooldown:triggerCooldown?HALLVALLA_TRIGGER_SKILL_COOLDOWN_SECONDS:(Number.isFinite(cooldown)?Math.max(0.5,cooldown+(rarity-1)*(Number.isFinite(cooldownStep)?cooldownStep:0)):null)
  };
}
function hvSkillRoman(n){
  const values=[[10,"X"],[9,"IX"],[5,"V"],[4,"IV"],[1,"I"]];let v=Math.max(1,Math.min(15,Math.floor(Number(n)||1))),out="";
  for(const [value,symbol] of values){while(v>=value){out+=symbol;v-=value;}}
  return out||"I";
}
function hvSkillCopyId(){try{return `UC-${crypto.randomUUID()}`;}catch(_){return `UC-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`;}}
function hvSkillGetProfile(){return typeof getPlayerProfile==="function"?getPlayerProfile():{};}
function hvSkillSaveProfile(profile,reason="unit_skills"){
  if(typeof savePlayerProfile==="function")savePlayerProfile(profile);
  try{
    if(typeof globalThis.hallvallaUploadCloudSave==="function"&&typeof auth!=="undefined"&&auth?.currentUser&&!auth.currentUser.isAnonymous){
      void globalThis.hallvallaUploadCloudSave(auth.currentUser,{force:true,reason}).catch(()=>{});
    }
  }catch(_){}
}
function hvSkillLegacyMasteryKey(entity){return typeof normalizeUnitMasteryName==="function"?normalizeUnitMasteryName(entity?.name||"").toLowerCase():hvSkillNorm(entity?.name||"");}
function hvSkillCopyMasteryKey(entity){const id=String(entity?.unitCopyId||"").trim();return id?`copy:${id.toLowerCase()}`:"";}


function hvSkillNormalizeCopyBook(profile){
  const source=profile?.unitSkillCopies&&typeof profile.unitSkillCopies==="object"?profile.unitSkillCopies:{};
  const byKey=source.byKey&&typeof source.byKey==="object"?source.byKey:{};
  const out={version:HALLVALLA_UNIT_SKILL_SCHEMA,byKey:{}};
  for(const [key,list] of Object.entries(byKey)){
    out.byKey[key]=(Array.isArray(list)?list:[]).filter(Boolean).map(rec=>({
      id:String(rec.id||hvSkillCopyId()),
      key:String(rec.key||key),
      name:String(rec.name||hvSkillUnitMeta(key)?.name||key),
      rarity:String(rec.rarity||hvSkillUnitMeta(key)?.rarity||"Básica"),
      active:rec.active!==false,
      createdAt:Number(rec.createdAt||Date.now()),
      learnedSkillIds:hvSkillUnique(rec.learnedSkillIds||[]).filter(id=>!!HALLVALLA_UNIT_SKILL_BANK[id]),
      talentTierReached:Math.max(1,Math.min(15,Math.floor(Number(rec.talentTierReached)||1))),
      masteryRank:Math.max(0,Math.min(45,Math.floor(Number(rec.masteryRank||rec.unitMasteryRank)||0)))
    }));
  }
  return out;
}

function hvSkillCollectionUnits(){
  let collection={cards:[]};
  try{collection=typeof getPlayerCollection==="function"?getPlayerCollection():JSON.parse(localStorage.getItem("hallvalla_player_collection")||'{"cards":[]}');}catch(_){}
  const cards=Array.isArray(collection?.cards)?collection.cards:[];
  return cards.map(raw=>{
    const template=(typeof CARD_TEMPLATES!=="undefined"?CARD_TEMPLATES:[]).find(card=>String(card?.key||"")===String(raw?.key||""))||{};
    const card={...template,...raw};
    const meta=hvSkillUnitMeta(card.key);
    if(!card.type&&meta)card.type="unit";
    return {card,qty:Math.max(0,Math.floor(Number(raw?.qty||0)))};
  }).filter(entry=>entry.qty>0&&String(entry.card?.type||"")==="unit"&&!entry.card?.leader);
}

function ensureHallvallaUnitSkillCopies(){
  const profile=hvSkillGetProfile();
  const original=profile?.unitSkillCopies?.byKey||{};
  const book=hvSkillNormalizeCopyBook(profile);
  let changed=false;
  const seenIds=new Set();
  for(const list of Object.values(book.byKey))for(const rec of list){
    if(!rec.id||seenIds.has(rec.id)){rec.id=hvSkillCopyId();changed=true;}
    seenIds.add(rec.id);
  }
  for(const [key,list] of Object.entries(original)){
    for(let index=0;index<(Array.isArray(list)?list.length:0);index++){
      if(!list[index]?.id&&book.byKey[key]?.[index])changed=true;
    }
  }
  for(const {card,qty} of hvSkillCollectionUnits()){
    const key=String(card.key||"");if(!key)continue;
    const meta=hvSkillUnitMeta(key)||{name:card.name||key,rarity:card.rarity||"Básica"};
    const list=book.byKey[key]||(book.byKey[key]=[]);
    const mastery=typeof normalizeUnitMasteryBook==="function"?normalizeUnitMasteryBook(profile.unitMastery||{}):(profile.unitMastery||{});
    const legacyKey=hvSkillLegacyMasteryKey(card);
    const legacyKills=Math.max(0,Number(mastery?.[legacyKey]?.kills||0));
    const rankFromKills=typeof getUnitMasteryRankFromKills==="function"?getUnitMasteryRankFromKills(legacyKills):1;
    const explicitRank=Math.max(0,Number(card.masteryRank||card.unitMasteryRank||0));
    const historicalRank=Math.max(rankFromKills,explicitRank);
    const reachedTier=hvSkillTierFromRank(historicalRank);
    let active=list.filter(rec=>rec.active!==false);
    while(active.length<qty){
      // Recuperar exactamente el ID, habilidades y Tier de una copia anterior.
      const dormant=list.find(rec=>rec.active===false);
      if(dormant){dormant.active=true;active.push(dormant);changed=true;continue;}
      const rec={id:hvSkillCopyId(),key,name:meta.name||card.name||key,rarity:meta.rarity||card.rarity||"Básica",active:true,createdAt:Date.now(),learnedSkillIds:[],talentTierReached:reachedTier,masteryRank:historicalRank};
      list.push(rec);active.push(rec);changed=true;
    }
    if(active.length>qty){
      // Nunca se eliminan registros históricos de una copia.
      for(const rec of active.slice(qty)){rec.active=false;changed=true;}
    }
    for(const rec of list){
      const properName=String(meta.name||card.name||key);
      const rarity=String(meta.rarity||card.rarity||"Básica");
      if(rec.name!==properName){rec.name=properName;changed=true;}
      if(rec.rarity!==rarity){rec.rarity=rarity;changed=true;}
      if(rec.masteryRank<historicalRank){rec.masteryRank=historicalRank;changed=true;}
      if(rec.talentTierReached<reachedTier){rec.talentTierReached=reachedTier;changed=true;}
    }
  }
  if(changed)hvSkillSaveProfile({...profile,unitSkillCopies:book},"unit_skill_copy_reconcile_v257");
  return book;
}
function hvSkillFindCopy(copyId,profile=hvSkillGetProfile()){
  const id=String(copyId||"");if(!id)return null;
  const book=hvSkillNormalizeCopyBook(profile);
  for(const list of Object.values(book.byKey||{})){
    const rec=(list||[]).find(item=>String(item?.id||"")===id);
    if(rec)return rec;
  }
  return null;
}
function hvSkillFindCopyMutable(copyId,book){
  const id=String(copyId||"");if(!id)return null;
  for(const list of Object.values(book?.byKey||{})){
    const rec=(list||[]).find(item=>String(item?.id||"")===id);
    if(rec)return rec;
  }
  return null;
}
function hvSkillUnitMeta(key){
  const safe=String(key||"");
  return globalThis.HALLVALLA_CONTENT_GENERATED?.assignments?.[safe]||HALLVALLA_UNIT_SKILL_ASSIGNMENTS[safe]||null;
}

function assignHallvallaUnitCopyIdsToDeck(deck=[]){
  const profile=hvSkillGetProfile();
  const book=ensureHallvallaUnitSkillCopies();
  const used=new Set();
  return (Array.isArray(deck)?deck:[]).map(card=>{
    if(!card||String(card.type||"")!=="unit"||card.leader)return card;
    const key=String(card.key||"");
    const meta=hvSkillUnitMeta(key);
    if(!meta)return card;
    const list=(book.byKey[key]||[]).filter(rec=>rec.active!==false);
    let rec=list.find(item=>String(item.id)===String(card.unitCopyId||"")&&!used.has(item.id));
    if(!rec)rec=list.find(item=>!used.has(item.id));
    if(!rec){
      rec={id:hvSkillCopyId(),key,name:meta.name||card.name||key,rarity:meta.rarity||card.rarity||"Básica",active:true,createdAt:Date.now(),learnedSkillIds:[],talentTierReached:1,masteryRank:1};
      (book.byKey[key]||(book.byKey[key]=[])).push(rec);
      const nextProfile={...profile,unitSkillCopies:book};hvSkillSaveProfile(nextProfile,"unit_skill_virtual_copy");
    }
    used.add(rec.id);
    return {...card,unitCopyId:rec.id,unitLearnedSkillIds:[...(rec.learnedSkillIds||[])],unitInnateSkillIds:[...(meta.innate||[])]};
  });
}

function hvSkillInstallDeckWrappers(){
  if(globalThis.__HALLVALLA_UNIT_SKILL_DECK_WRAPPED__)return;
  globalThis.__HALLVALLA_UNIT_SKILL_DECK_WRAPPED__=true;
  const originalSave=globalThis.saveDeck;
  const originalGet=globalThis.getSavedDeck;
  if(typeof originalSave==="function"){
    globalThis.saveDeck=function(deck){return originalSave(assignHallvallaUnitCopyIdsToDeck(deck));};
  }
  if(typeof originalGet==="function"){
    globalThis.getSavedDeck=function(){
      const raw=originalGet();
      const assigned=assignHallvallaUnitCopyIdsToDeck(raw);
      try{
        if(JSON.stringify(raw)!==JSON.stringify(assigned))localStorage.setItem("hallvalla_current_deck",JSON.stringify(assigned));
      }catch(_){}
      return assigned;
    };
  }
}

function hvSkillCompatible(skill,unitKey){
  const meta=hvSkillUnitMeta(unitKey);if(!skill||!meta)return false;
  const exclusive=Array.isArray(skill.exclusiveKeys)?skill.exclusiveKeys:[];
  if(exclusive.length&&!exclusive.includes(unitKey))return false;
  const uw=new Set(meta.weaponTags||[]),uc=new Set(meta.classTags||[]);
  const weapon=(skill.weapons||[]).some(tag=>tag==="any"||uw.has("any")||uw.has(tag));
  const klass=(skill.classes||[]).some(tag=>tag==="any"||uc.has("any")||uc.has(tag));
  return weapon&&klass;
}
function hvSkillHash(text){
  let h=2166136261;for(const ch of String(text||"")){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;
}
function hvSkillOptionsForCopy(rec,tier){
  const meta=hvSkillUnitMeta(rec?.key);if(!meta)return[];
  const blocked=new Set([...(meta.innate||[]),...(rec.learnedSkillIds||[])]);
  const eligible=Object.values(HALLVALLA_UNIT_SKILL_BANK).filter(skill=>!blocked.has(skill.id)&&hvSkillCompatible(skill,rec.key));
  const seed=`${rec.id}|${rec.key}|tier:${tier}`;
  const specialized=[],universal=[];
  for(const skill of eligible){
    const generic=(skill.weapons||[]).includes("any")&&(skill.classes||[]).includes("any");
    (generic?universal:specialized).push(skill);
  }
  const sortPool=pool=>pool.sort((a,b)=>hvSkillHash(`${seed}|${a.id}`)-hvSkillHash(`${seed}|${b.id}`)||String(a.id).localeCompare(String(b.id)));
  return [...sortPool(specialized),...sortPool(universal)].slice(0,3).map(skill=>skill.id);
}
function hvSkillNormalizePending(profile){
  return (Array.isArray(profile?.unitSkillPendingChoices)?profile.unitSkillPendingChoices:[]).filter(item=>item&&item.copyId&&Array.isArray(item.options)&&item.options.length);
}

function queueHallvallaUnitSkillChoice(unit,result){
  try{
    const copyId=String(unit?.unitCopyId||"");if(!copyId)return null;
    const profile=hvSkillGetProfile(),book=hvSkillNormalizeCopyBook(profile);
    const rec=hvSkillFindCopyMutable(copyId,book);if(!rec)return null;
    const top=Math.max(1,Math.min(15,Number(result?.afterTier||hvSkillTierFromRank(result?.afterRank||1))));
    const pending=hvSkillNormalizePending(profile);
    // El evento no es el único origen de las elecciones: el Tier ganado manda.
    const missing=hvSkillUnclaimedTiersForCopy(rec,profile).filter(tier=>tier<=top);
    if(!missing.length)return null;
    const tier=missing[0],options=hvSkillOptionsForCopy(rec,tier);
    if(options.length!==3)return null;
    rec.talentTierReached=Math.max(Number(rec.talentTierReached||1),top);
    const item={id:'skill-choice:'+copyId+':'+tier,copyId,unitKey:rec.key,unitName:rec.name,rarity:rec.rarity,tier,options,createdAt:Date.now()};
    pending.push(item);
    hvSkillSaveProfile({...profile,unitSkillCopies:book,unitSkillPendingChoices:pending},'unit_skill_tier_up');
    setTimeout(()=>maybeShowHallvallaUnitSkillChoice(),900);
    return item;
  }catch(error){console.warn('[HallValla][Skills] Falló nueva elección:',error);return null;}
}
function hvSkillChoose(pendingId,skillId){
  const profile=hvSkillGetProfile(),book=hvSkillNormalizeCopyBook(profile),pending=hvSkillNormalizePending(profile);
  const item=pending.find(row=>String(row.id)===String(pendingId));if(!item||!item.options.includes(skillId))return false;
  const rec=hvSkillFindCopyMutable(item.copyId,book);if(!rec)return false;
  const meta=hvSkillUnitMeta(rec.key)||{innate:[]};
  const chosenSkill=HALLVALLA_UNIT_SKILL_BANK[skillId];
  if(!chosenSkill||!hvSkillCompatible(chosenSkill,rec.key))return false;
  if(!hvSkillPendingTierStillNeeded(item,rec,profile))return false;
  if((meta.innate||[]).includes(skillId)||(rec.learnedSkillIds||[]).includes(skillId))return false;
  rec.learnedSkillIds=hvSkillUnique([...(rec.learnedSkillIds||[]),skillId]);
  const nextPending=pending.filter(row=>String(row.id)!==String(item.id));
  hvSkillSaveProfile({...profile,unitSkillCopies:book,unitSkillPendingChoices:nextPending},"unit_skill_choice");
  try{
    const saved=typeof globalThis.getSavedDeck==="function"?globalThis.getSavedDeck():[];
    if(Array.isArray(saved)&&typeof globalThis.saveDeck==="function")void globalThis.saveDeck(saved);
  }catch(_){}
  return true;
}

function hvSkillDescribe(skill,entity){
  const scaled=hvSkillScale(skill,entity),parts=[];
  if(scaled.value!==null&&String(skill.scale||"").trim())parts.push(`${skill.scale}: ${Number(scaled.value.toFixed?.(2)??scaled.value)}`);
  if(scaled.proc!==null)parts.push(`Probabilidad: ${Math.round(scaled.proc)}%`);
  if(scaled.duration!==null)parts.push(`Duración: ${Number(scaled.duration.toFixed?.(1)??scaled.duration)} s`);
  if(scaled.cooldown!==null)parts.push(`Enfriamiento: ${Number(scaled.cooldown.toFixed?.(1)??scaled.cooldown)} s`);
  return parts.join(" · ");
}
