function hvGlossaryEsc(value){
  return String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
}
function hvGlossaryEntries(){
  const out=[];
  for(const skill of Object.values(HALLVALLA_UNIT_SKILL_BANK)){
    out.push({
      id:skill.id,
      name:skill.name,
      category:skill.category||"Habilidad",
      effect:hvSkillPlayerText(skill,{rarity:"Básica"}),
      trigger:"",
      numbers:"",
      origin:[skill.origin,skill.reference].filter(Boolean).join(" · "),
      weapons:(skill.weapons||[]).join(", "),
      classes:(skill.classes||[]).join(", "),
      counters:skill.counters||"",
      source:"Banco de habilidades",
      tags:skill.tags||[]
    });
  }
  for(const entry of HALLVALLA_ENGINE_GLOSSARY){
    out.push({...entry,id:`ENGINE-${hvSkillNorm(entry.name)}`,source:"Regla del motor",origin:"",weapons:"",classes:"",counters:"",numbers:""});
  }
  try{
    if(typeof DET_CARD_EFFECT_SECTIONS!=="undefined"){
      for(const [cardKey,sections] of Object.entries(DET_CARD_EFFECT_SECTIONS||{})){
        for(const section of (Array.isArray(sections)?sections:[])){
          if(!section?.title||!section?.body)continue;
          out.push({
            id:`CARD-${cardKey}-${hvSkillNorm(section.title)}`,
            name:section.title,
            category:"Magia / Trampa",
            effect:section.body,
            trigger:"Según la condición de la carta",
            source:`Carta: ${cardKey}`,
            origin:"",
            weapons:"",
            classes:"",
            counters:"",
            numbers:"",
            tags:[section.kind||"effect"]
          });
        }
      }
    }
  }catch(_){}
  const seen=new Set();
  return out.filter(entry=>{
    const sig=`${hvSkillNorm(entry.name)}|${hvSkillNorm(entry.effect)}`;
    if(seen.has(sig))return false;
    seen.add(sig);
    return true;
  }).sort((a,b)=>String(a.category||"").localeCompare(String(b.category||""),"es")||String(a.name||"").localeCompare(String(b.name||""),"es"));
}
function hvSkillEnsureGlossaryUi(){
  if(document.getElementById("hvEffectGlossaryOverlay"))return;
  const style=document.createElement("style");
  style.id="hvEffectGlossaryStyle";
  style.textContent=`
  #hvEffectGlossaryOverlay{position:fixed;inset:0;z-index:1000001;background:rgba(0,0,0,.84);display:flex;align-items:center;justify-content:center;padding:16px;font-family:Arial,sans-serif}
  #hvEffectGlossaryOverlay.hidden{display:none}
  .hv-glossary-card{width:min(1180px,97vw);height:min(88vh,760px);display:flex;flex-direction:column;overflow:hidden;border:2px solid #b88a39;border-radius:18px;background:linear-gradient(180deg,#21170f,#0b0907);box-shadow:0 24px 90px #000;color:#f5e8c8}
  .hv-glossary-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;padding:18px 20px 10px;border-bottom:1px solid rgba(203,159,73,.35)}
  .hv-glossary-head h2{margin:0;color:#ffd77e;font:700 28px Georgia,serif}.hv-glossary-head p{margin:5px 0 0;color:#cdbf9f;font-size:13px}
  .hv-glossary-close{width:40px;height:40px;border-radius:50%;border:1px solid #b88a39;background:#23180d;color:#ffd77e;font-size:26px;cursor:pointer}
  .hv-glossary-tools{display:grid;grid-template-columns:1fr 250px auto;gap:10px;padding:12px 20px}
  .hv-glossary-tools input,.hv-glossary-tools select{min-height:40px;border:1px solid #73582d;border-radius:9px;background:#0f0c09;color:#fff;padding:0 12px}
  .hv-glossary-count{display:flex;align-items:center;color:#e1ca98;font-weight:700;white-space:nowrap}
  .hv-glossary-list{overflow:auto;padding:0 20px 20px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
  .hv-glossary-entry{border:1px solid rgba(175,132,57,.52);border-radius:11px;background:rgba(59,42,24,.66);padding:12px}
  .hv-glossary-entry h3{margin:0 0 3px;color:#ffd77e;font:700 18px Georgia,serif}.hv-glossary-meta{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#bca77b}
  .hv-glossary-effect{margin:8px 0;color:#f6f1e8;font-size:14px;line-height:1.38}.hv-glossary-line{font-size:12px;line-height:1.35;color:#cfc4ad;margin-top:4px}
  .hv-glossary-id{color:#87c8ff}.hv-glossary-empty{grid-column:1/-1;text-align:center;padding:40px;color:#cdbf9f}
  @media(max-width:820px){.hv-glossary-tools{grid-template-columns:1fr}.hv-glossary-list{grid-template-columns:1fr}.hv-glossary-card{height:94vh}}
  `;
  document.head.appendChild(style);
  const overlay=document.createElement("div");
  overlay.id="hvEffectGlossaryOverlay";
  overlay.className="hidden";
  overlay.innerHTML=`<section class="hv-glossary-card" role="dialog" aria-modal="true" aria-labelledby="hvEffectGlossaryTitle">
    <header class="hv-glossary-head"><div><h2 id="hvEffectGlossaryTitle">Glosario de efectos</h2><p>Catálogo vigente al ${HALLVALLA_EFFECT_GLOSSARY_DATE}. Incluye habilidades, estados, reglas de clase y efectos de magias/trampas.</p></div><button class="hv-glossary-close" type="button" aria-label="Cerrar">×</button></header>
    <div class="hv-glossary-tools"><input id="hvGlossarySearch" type="search" placeholder="Buscar: fuego, arco, exorcismo, Sangrado..." autocomplete="off"><select id="hvGlossaryCategory" aria-label="Filtrar categoría"><option value="">Todas las categorías</option></select><div id="hvGlossaryCount" class="hv-glossary-count"></div></div>
    <div id="hvGlossaryList" class="hv-glossary-list"></div>
  </section>`;
  document.body.appendChild(overlay);
  const close=()=>overlay.classList.add("hidden");
  overlay.querySelector(".hv-glossary-close").addEventListener("click",close);
  overlay.addEventListener("click",ev=>{if(ev.target===overlay)close();});
  overlay.querySelector("#hvGlossarySearch").addEventListener("input",()=>hvGlossaryRender());
  overlay.querySelector("#hvGlossaryCategory").addEventListener("change",()=>hvGlossaryRender());
}
function hvGlossaryRender(){
  hvSkillEnsureGlossaryUi();
  const overlay=document.getElementById("hvEffectGlossaryOverlay"),list=overlay?.querySelector("#hvGlossaryList"),category=overlay?.querySelector("#hvGlossaryCategory"),search=overlay?.querySelector("#hvGlossarySearch"),count=overlay?.querySelector("#hvGlossaryCount");
  if(!overlay||!list||!category||!search||!count)return;
  const entries=hvGlossaryEntries();
  if(category.options.length<=1){
    [...new Set(entries.map(entry=>String(entry.category||"Otros")).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"es")).forEach(value=>{
      const option=document.createElement("option");option.value=value;option.textContent=value;category.appendChild(option);
    });
  }
  const q=hvSkillNorm(search.value),cat=String(category.value||"");
  const filtered=entries.filter(entry=>{
    if(cat&&String(entry.category)!==cat)return false;
    if(!q)return true;
    return hvSkillNorm([entry.id,entry.name,entry.category,entry.effect,entry.trigger,entry.origin,entry.weapons,entry.classes,entry.counters,entry.source,(entry.tags||[]).join(" ")].join(" ")).includes(q);
  });
  count.textContent=`${filtered.length} / ${entries.length}`;
  list.innerHTML=filtered.length?filtered.map(entry=>{
    const skill=HALLVALLA_UNIT_SKILL_BANK[entry.id];
    if(skill){
      const basic=hvSkillPlayerText(skill,{rarity:"Básica"});
      const legendary=hvSkillPlayerText(skill,{rarity:"Legendaria"});
      return `<article class="hv-glossary-entry"><h3>${hvGlossaryEsc(skill.name)}</h3><div class="hv-glossary-effect"><b>Básica:</b> ${hvGlossaryEsc(basic)}</div>${legendary!==basic?`<div class="hv-glossary-line"><b>Legendaria:</b> ${hvGlossaryEsc(legendary)}</div>`:""}</article>`;
    }
    const scale=skill?hvSkillDescribe(skill,{rarity:"Básica"}):"";
    const scaleMax=skill?hvSkillDescribe(skill,{rarity:"Semidiós"}):"";
    return `<article class="hv-glossary-entry"><div class="hv-glossary-meta"><span class="hv-glossary-id">${hvGlossaryEsc(entry.id||"")}</span> · ${hvGlossaryEsc(entry.category||"Efecto")} · ${hvGlossaryEsc(entry.source||"")}</div><h3>${hvGlossaryEsc(entry.name||"Efecto")}</h3><div class="hv-glossary-effect">${hvGlossaryEsc(entry.effect||"")}</div>${entry.trigger?`<div class="hv-glossary-line"><b>Activación:</b> ${hvGlossaryEsc(entry.trigger)}</div>`:""}${skill&&scale?`<div class="hv-glossary-line"><b>Básica:</b> ${hvGlossaryEsc(scale)}</div>`:""}${skill&&scaleMax&&scaleMax!==scale?`<div class="hv-glossary-line"><b>Semidiós:</b> ${hvGlossaryEsc(scaleMax)}</div>`:""}${entry.weapons?`<div class="hv-glossary-line"><b>Armas:</b> ${hvGlossaryEsc(entry.weapons)}</div>`:""}${entry.classes?`<div class="hv-glossary-line"><b>Clases:</b> ${hvGlossaryEsc(entry.classes)}</div>`:""}${entry.counters?`<div class="hv-glossary-line"><b>Contrajuego:</b> ${hvGlossaryEsc(entry.counters)}</div>`:""}${entry.origin?`<div class="hv-glossary-line"><b>Base:</b> ${hvGlossaryEsc(entry.origin)}</div>`:""}</article>`;
  }).join(""):`<div class="hv-glossary-empty">No hay efectos que coincidan con ese filtro.</div>`;
}
function openHallvallaEffectsGlossary(){
  hvSkillEnsureGlossaryUi();
  hvGlossaryRender();
  const overlay=document.getElementById("hvEffectGlossaryOverlay");
  if(overlay)overlay.classList.remove("hidden");
}
function hvSkillInstallGlossaryAccess(){
  const settings=document.querySelector("#settingsPanel .settings-learning-zone");
  if(settings&&!document.getElementById("openEffectsGlossaryBtn")){
    const button=document.createElement("button");
    button.id="openEffectsGlossaryBtn";
    button.type="button";
    button.className="btn ghost full";
    button.textContent="Glosario de efectos";
    button.addEventListener("click",openHallvallaEffectsGlossary);
    settings.appendChild(button);
  }
  // Si la guía de reglas ya existe, añade acceso directo también allí.
  const guideActions=document.querySelector("#statGuideModal .stat-guide-actions");
  if(guideActions&&!document.getElementById("statGuideGlossaryBtn")){
    const button=document.createElement("button");
    button.id="statGuideGlossaryBtn";
    button.type="button";
    button.className="btn ghost";
    button.textContent="Glosario";
    button.addEventListener("click",openHallvallaEffectsGlossary);
    guideActions.prepend(button);
  }
}
function hvSkillWrapGuideForGlossary(){
  if(globalThis.__HALLVALLA_STAGE4_GUIDE_GLOSSARY__)return;
  const original=typeof globalThis.openStatGuideModal==="function"?globalThis.openStatGuideModal:null;
  if(!original)return;
  globalThis.__HALLVALLA_STAGE4_GUIDE_GLOSSARY__=true;
  globalThis.openStatGuideModal=function(...args){
    const result=original(...args);
    hvSkillInstallGlossaryAccess();
    return result;
  };
}

function hallvallaSkillLocalTestChoice(unitKey="archer"){
  const local=(typeof location!=="undefined")&&(/^(localhost|127\.0\.0\.1)$/i.test(location.hostname)||location.protocol==="file:");
  if(!local)return false;
  const key=String(unitKey||"archer"),book=ensureHallvallaUnitSkillCopies(),list=(book.byKey[key]||[]).filter(rec=>rec.active!==false),rec=list[0];
  if(!rec){console.warn("[HallValla][Skills] No hay copia activa para prueba:",key);return false;}
  const nextTier=Math.min(15,Math.max(2,Number(rec.talentTierReached||1)+1));
  rec.talentTierReached=Math.max(1,nextTier-1);
  const profile=hvSkillGetProfile();hvSkillSaveProfile({...profile,unitSkillCopies:book},"unit_skill_local_test");
  const fake={unitCopyId:rec.id,key:rec.key,name:rec.name,rarity:rec.rarity,owner:typeof myPlayer!=="undefined"?(myPlayer||1):1};
  const item=queueHallvallaUnitSkillChoice(fake,{afterTier:nextTier,afterRank:(nextTier-1)*3+1});
  if(item)setTimeout(()=>maybeShowHallvallaUnitSkillChoice(),100);
  return !!item;
}

/* HALLVALLA_ARCHER_PERSONAL_REPAIR_V1
   Reparacion voluntaria, iniciada SOLO con ?hvRepararArquera=1.
   No altera ninguna cuenta hasta pulsar una opcion y confirmar. */
function hvSkillShowPersonalArcherRepair(){
  if(new URLSearchParams(location.search).get("hvRepararArquera")!=="1")return;
  if(document.getElementById("hvPersonalArcherRepairPanel"))return;
  const invalidIds=new Set(["HV-134","HV-135","HV-142","HV-144","HV-145","HV-148","HV-152"]);
  const newSkillId="HV-001";
  const shell=document.createElement("section");
  shell.id="hvPersonalArcherRepairPanel";
  shell.style.cssText="position:fixed;top:18px;right:18px;z-index:2147483647;width:min(485px,calc(100vw - 28px));max-height:calc(100vh - 36px);overflow:auto;background:#21170c;border:2px solid #cda650;border-radius:16px;padding:17px;box-shadow:0 14px 50px #000;color:#ffebc1;font:15px/1.5 Arial,sans-serif;";
  const heading=document.createElement("h3");
  heading.textContent="Correccion personal - Arquera del Desierto";
  heading.style.cssText="font:700 20px Arial;color:#ffd47a;margin:0 0 8px";
  shell.appendChild(heading);
  const sub=document.createElement("div");
  sub.textContent="Cambia solo la habilidad de Sigilo incorrecta por Ojo de Aguila (+2 AT en el siguiente ataque a distancia; 30 s de recarga). No modifica otras copias ni el Tier.";
  shell.appendChild(sub);
  const area=document.createElement("div");
  area.style.cssText="margin:12px 0;max-height:45vh;overflow:auto";
  shell.appendChild(area);
  const message=document.createElement("div");
  message.style.cssText="font-size:13px;color:#bde4fc;white-space:pre-wrap;margin:6px 0";
  shell.appendChild(message);
  const foot=document.createElement("div");
  foot.style.cssText="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px";
  shell.appendChild(foot);
  const createButton=(label,parent,fn)=>{
    const button=document.createElement("button");button.type="button";button.textContent=label;
    button.style.cssText="background:#583d1c;color:#fff3c5;border:1px solid #d6ab55;border-radius:8px;padding:8px 10px;margin:4px 0;cursor:pointer;text-align:left";
    button.addEventListener("click",fn);parent.appendChild(button);return button;
  };
  const render=()=>{
    area.replaceChildren();message.textContent="";
    const profile=hvSkillGetProfile(),records=profile?.unitSkillCopies?.byKey?.archer||[];
    const active=records.filter(rec=>rec&&rec.active!==false);
    const pending=Array.isArray(profile?.unitSkillPendingChoices)?profile.unitSkillPendingChoices:[];
    const entries=[];
    active.forEach((rec,index)=>{
      for(const id of (rec.learnedSkillIds||[])){
        if(invalidIds.has(id))entries.push({copyId:String(rec.id),index,oldId:id,kind:"learned"});
      }
      for(const item of pending){
        if(String(item.copyId)!==String(rec.id))continue;
        for(const id of item.options||[]){
          if(invalidIds.has(id))entries.push({copyId:String(rec.id),index,oldId:id,kind:"pending",pendingId:String(item.id)});
        }
      }
    });
    if(!entries.length){
      message.textContent=active.length?"No hay habilidades de Sigilo erroneas detectadas en estas copias. No se modifico nada.":"No se encuentran copias activas. Inicia sesion, espera a que cargue tu coleccion y pulsa Revisar.";
      return;
    }
    for(const entry of entries){
      const oldName=HALLVALLA_UNIT_SKILL_BANK[entry.oldId]?.name||entry.oldId;
      const kind=entry.kind==="learned"?"Habilidad aprendida":"Opcion pendiente";
      const button=createButton(`Copia ${entry.index+1} - ${kind}: ${oldName} -> Ojo de Aguila`,area,()=>void apply(entry));
      button.style.display="block";button.style.width="100%";
    }
  };
  const apply=async entry=>{
    const oldName=HALLVALLA_UNIT_SKILL_BANK[entry.oldId]?.name||entry.oldId;
    const question=`Arquera del Desierto, copia ${entry.index+1}\n\nCambiar ${oldName} por Ojo de Aguila (+2 AT en un ataque a distancia, recarga 30 s).\n\nÂ¿Confirmar este cambio UNICAMENTE para esta copia?`;
    if(!window.confirm(question))return;
    const raw=localStorage.getItem("hallvalla_player_profile");
    if(!raw){message.textContent="No se encontro perfil guardado. No se modifico nada.";return;}
    const profile=hvSkillGetProfile(),book=hvSkillNormalizeCopyBook(profile);
    const rec=hvSkillFindCopyMutable(entry.copyId,book);
    if(!rec||rec.key!=="archer"||rec.active===false){message.textContent="Esa copia ya no esta disponible. No se modifico nada.";return;}
    if((rec.learnedSkillIds||[]).includes(newSkillId)){message.textContent="Esta copia ya aprendio Ojo de Aguila. No se modifico nada.";return;}
    const next={...profile,unitSkillCopies:book};
    if(entry.kind==="learned"){
      if(!(rec.learnedSkillIds||[]).includes(entry.oldId)){message.textContent="La habilidad original ya cambio. No se modifico nada.";return;}
      rec.learnedSkillIds=rec.learnedSkillIds.map(id=>id===entry.oldId?newSkillId:id);
    }else{
      const all=Array.isArray(profile.unitSkillPendingChoices)?profile.unitSkillPendingChoices:[];
      const item=all.find(row=>String(row.id)===entry.pendingId&&String(row.copyId)===entry.copyId);
      if(!item||(item.options||[]).includes(newSkillId)||(item.options||[]).filter(id=>id===entry.oldId).length!==1){
        message.textContent="La solicitud pendiente ya cambio o contiene Ojo de Aguila. No se modifico nada.";return;
      }
      next.unitSkillPendingChoices=all.map(row=>row===item?{...row,options:row.options.map(id=>id===entry.oldId?newSkillId:id)}:row);
    }
    const backupKey="hallvalla_backup_personal_arquera_"+Date.now();
    try{localStorage.setItem(backupKey,raw);}catch(e){message.textContent="No se pudo crear el respaldo. Se cancelo la correccion.";return;}
    if(typeof savePlayerProfile==="function")savePlayerProfile(next);
    else localStorage.setItem("hallvalla_player_profile",JSON.stringify(next));
    try{
      const deck=typeof getSavedDeck==="function"?getSavedDeck():null;
      if(Array.isArray(deck)&&typeof saveDeck==="function")saveDeck(deck);
    }catch(e){console.warn("[HallValla] El mazo se sincronizara en la siguiente carga:",e);}
    message.textContent=`Cambio local guardado. Respaldo: ${backupKey}. Intentando sincronizar con la nube...`;
    try{
      const account=typeof auth!=="undefined"?auth?.currentUser:null;
      if(account&&!account.isAnonymous&&typeof globalThis.hallvallaUploadCloudSave==="function"){
        await globalThis.hallvallaUploadCloudSave(account,{force:true,reason:"personal_archer_skill_fix_20261013"});
        message.textContent=`CORRECCION REALIZADA. Copia ${entry.index+1}: ${oldName} -> Ojo de Aguila. Perfil local y nube sincronizados. Respaldo: ${backupKey}`;
      }else{
        message.textContent=`CORRECCION LOCAL REALIZADA. Copia ${entry.index+1}: ${oldName} -> Ojo de Aguila. No se pudo confirmar guardado en nube; verifica tu sesion. Respaldo: ${backupKey}`;
      }
    }catch(err){console.warn("[HallValla] Cloud save no confirmado:",err);message.textContent=`CORRECCION LOCAL REALIZADA, pero la nube no confirmo el guardado. Respaldo: ${backupKey}`;}
    area.replaceChildren();
    createButton("Cerrar",foot,()=>shell.remove());
    console.info("[HallValla] Reparacion personal arquera",{copyId:entry.copyId,before:entry.oldId,after:newSkillId,backupKey});
  };
  createButton("Revisar copias",foot,render);
  createButton("Cerrar",foot,()=>shell.remove());
  document.body.appendChild(shell);
  render();
}
if(typeof location!=="undefined"&&new URLSearchParams(location.search).get("hvRepararArquera")==="1"){
  const startRepair=()=>setTimeout(hvSkillShowPersonalArcherRepair,1100);
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",startRepair,{once:true});
  else startRepair();
}

